const crypto = require('crypto');

const getSessionAdmin = (req) => {
  const admin = req && req.session && req.session.admin;
  if (!admin || !admin.username) return null;
  return admin;
};

const requireAdminSession = (req, res, next) => {
  const admin = getSessionAdmin(req);
  if (!admin) {
    res.status(401).json({ success: false, error: 'Admin authentication required' });
    return;
  }
  req.admin = admin;
  next();
};

const requireAdminRole = (...allowedRoles) => (req, res, next) => {
  if (!allowedRoles || allowedRoles.length === 0) {
    next();
    return;
  }

  const normalize = (value) => (value || '').toString().trim().toLowerCase();
  const allowed = new Set(allowedRoles.map(normalize).filter(Boolean));

  const roles = Array.isArray(req.admin?.roles) ? req.admin.roles : [];
  const hasRole = roles.map(normalize).some((role) => allowed.has(role));
  if (!hasRole) {
    res.status(403).json({ success: false, error: 'Admin authorization required' });
    return;
  }

  next();
};

const issueCsrfToken = (req) => {
  const token = crypto.randomBytes(32).toString('hex');
  if (!req.session) {
    return token;
  }
  req.session.csrfToken = token;
  return token;
};

const requireAdminCsrf = (req, res, next) => {
  // Only enforce CSRF for state-changing methods.
  const method = (req.method || '').toUpperCase();
  if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') {
    next();
    return;
  }

  const expected = (req.session && req.session.csrfToken) || '';
  const provided = (req.get('x-csrf-token') || '').toString();

  if (!expected || !provided) {
    res.status(403).json({ success: false, error: 'CSRF token missing or invalid' });
    return;
  }

  const expectedBuf = Buffer.from(expected, 'utf8');
  const providedBuf = Buffer.from(provided, 'utf8');

  if (expectedBuf.length !== providedBuf.length || !crypto.timingSafeEqual(expectedBuf, providedBuf)) {
    res.status(403).json({ success: false, error: 'CSRF token missing or invalid' });
    return;
  }

  next();
};

module.exports = {
  getSessionAdmin,
  requireAdminSession,
  requireAdminRole,
  issueCsrfToken,
  requireAdminCsrf,
};
